WITH gaps AS (SELECT *, CASE WHEN LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) IS NULL OR txn_time > LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) + INTERVAL '7' DAY THEN 1 ELSE 0 END AS is_new_session FROM transactions), sessionized AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM gaps) SELECT id, account_id, txn_type, amount, merchant, session_id, CASE WHEN txn_type RLIKE '^(REFUND|FEE)$' THEN 'GROUP_A' WHEN txn_type RLIKE '^(DEBIT|CREDIT)$' THEN 'EXTENDED' ELSE 'OTHER_ZONE' END AS txn_type_zone FROM sessionized ORDER BY session_id DESC
